<?php defined('ABSPATH') || exit; $base=home_url('/companion/'); $root='dungeon-master/campaigns/'.$campaign->id().'/encounters'; ?>
<section class="gmrc-encounter-board" aria-labelledby="gmrc-encounter-board-title"><header class="gmrc-encounter-board__hero"><div><p class="gmrc-dm-desk__eyebrow">Ledger III · <?php echo esc_html($campaign->name()); ?></p><h1 id="gmrc-encounter-board-title">The Encounter Board</h1><p>Prepare challenges, pin them to a Session when ready, marshal the opposition, and track each clash from preparation to completion.</p></div><?php if(!$campaign->isArchived()): ?><a class="gmrc-encounter-button" href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/create',$base)); ?>">Prepare an Encounter</a><?php endif; ?></header>
<?php if(!empty($flash['success'])): ?><p class="gmrc-encounter-flash" role="status"><?php echo esc_html($flash['success']); ?></p><?php endif; ?><?php if($campaign->isArchived()): ?><p class="gmrc-encounter-notice">This campaign is archived. Its Encounter Board is preserved as read-only history.</p><?php endif; ?>
<div class="gmrc-encounter-grid"><?php if(($encounters??[])===[]): ?><article class="gmrc-encounter-card"><p class="gmrc-encounter-card__status">No encounters pinned</p><h2>The board is clear</h2><p>Prepare the first challenge for this campaign when inspiration strikes.</p></article><?php endif; ?><?php foreach(($encounters??[]) as $entry): ?><article class="gmrc-encounter-card gmrc-encounter-card--<?php echo esc_attr($entry->status()); ?>"><p class="gmrc-encounter-card__status"><?php echo esc_html(ucfirst($entry->status()).' · '.ucfirst($entry->threat()).' threat'); ?></p><h2><?php echo esc_html($entry->title()); ?></h2><p><?php echo esc_html($entry->location()!==''?$entry->location():'Location not yet set'); ?></p><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$entry->id(),$base)); ?>">Open Encounter →</a></article><?php endforeach; ?></div><p class="gmrc-encounter-back"><a href="<?php echo esc_url(add_query_arg('gmrc_route','dungeon-master/campaigns/'.$campaign->id(),$base)); ?>">← Back to Campaign Chronicle</a></p></section>
